import itertools
def feats(I, marker, rsep, csep):
    H,W=len(I),len(I[0])
    rr=[-1]+rsep+[H]; cc=[-1]+csep+[W]
    rb=[(rr[i]+1,rr[i+1]) for i in range(len(rr)-1)]
    cb=[(cc[i]+1,cc[i+1]) for i in range(len(cc)-1)]
    F=[]
    for a,b in rb:
        for x,y in cb:
            pos=[(r,c) for r in range(a,b) for c in range(x,y) if I[r][c]==marker]
            S=set(pos)
            def adj4(p): return sum((p[0]+dr,p[1]+dc) in S for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)])
            def adj8(p): return sum((p[0]+dr,p[1]+dc) in S for dr,dc in itertools.product([-1,0,1],repeat=2) if (dr,dc)!=(0,0))
            n=len(pos)
            # comps4
            comps4=0; seen=set()
            for p in pos:
                if p in seen: continue
                comps4+=1; st=[p]
                while st:
                    q=st.pop()
                    if q in seen: continue
                    seen.add(q)
                    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        if (q[0]+dr,q[1]+dc) in S: st.append((q[0]+dr,q[1]+dc))
            rows=set(p[0]-a for p in pos); cols=set(p[1]-x for p in pos)
            # isolated: no marker 4-adj within grid
            iso=sum(adj4(p)==0 for p in pos)
            iso8=sum(adj8(p)==0 for p in pos)
            bh=b-a; bw=y-x
            F.append(dict(n=n,comps4=comps4,iso=iso,iso8=iso8,
                          nrow=len(rows),ncol=len(cols),bh=bh,bw=bw,
                          srow=sum(r-a for r,c in pos), scol=sum(c-x for r,c in pos)))
    return F,len(rb),len(cb)
